 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    if (!event.payload.isInitialPageLoad) {
        if (event.payload.selectedTab == "id=diagnostics") {
            return {
                route: "diagnostics-home",
                fields: null,
                params: null,
                redirect: true,
                passiveNavigation: null,
                title: null,
                multiInstField: null,
                targetRoute: null,
                external: {},
                navigationOptions: null
            };
        } else {
            return {
                route: "dashboard",
                fields: null,
                params: null,
                redirect: true,
                passiveNavigation: null,
                title: null,
                multiInstField: null,
                targetRoute: null,
                external: {},
                navigationOptions: null
            };
        }
    }
})

