/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		params: {
			"freshpage": "false",
			"tabname": event.payload.selectedTab.replace("id=","")
		}
	};
}
